function fitText(g,txt,maxW,px,min,weight){px=px||48;do{g.font=`${weight||"bold"} ${px}px ${FF()}`;px-=2}while(g.measureText(txt).width>maxW&&px>(min||18));return g.measureText(txt).width<=maxW}
async function makeShare(fmt){const [W,H]={sq:[1080,1080],wide:[1200,630],story:[1080,1920]}[fmt];R.setSize(1080,1080,false);R.render(sc,cam);
  const c=document.createElement("canvas");c.width=W;c.height=H;const g=c.getContext("2d"),b=BGS[$("bg").value]||BGS.night,gr=g.createRadialGradient(W/2,H*.42,40,W/2,H*.5,Math.max(W,H)*.75);gr.addColorStop(0,b[0]);gr.addColorStop(1,b[1]);g.fillStyle=gr;g.fillRect(0,0,W,H);
  const light=$("bg").value=="light",ink=light?"#1d1d1b":"#fff",sub=light?"#57534e":"#cbd5e1",title=$("trip").value||"",line2=[dt(),$("tsub").value].filter(Boolean).join(" · ");g.direction=LANG=="en"?"ltr":"rtl";g.textAlign="center";
  let tx=W/2,ty,mw=W-80;
  if(fmt=="wide"){g.drawImage(vc,0,0,H,H);tx=(H+W)/2;mw=W-H-60;ty=H*.42}else if(fmt=="story"){g.drawImage(vc,0,240,1080,1080);ty=1440}else{g.drawImage(vc,70,10,940,940);ty=1010}
  const w=vc.clientWidth;R.setSize(w,w,false);
  g.fillStyle=ink;fitText(g,title,mw,fmt=="wide"?54:70,24);g.fillText(title,tx,ty);g.fillStyle=sub;if(line2){fitText(g,line2,mw,30,16,"normal");g.fillText(line2,tx,ty+(fmt=="wide"?54:60))}
  g.fillStyle=sub;g.globalAlpha=.7;g.font=`22px ${FF()}`;g.fillText(location.host,fmt=="wide"?tx:W/2,H-18);g.globalAlpha=1;
  return new Promise(r=>c.toBlob(r,"image/png"))}
